use ulw_loop_core::command_types::CreateGoalsOptions;
use ulw_loop_core::sdk::{ulw_loop_manifest, AgentToolkit, ToolkitContext, ToolkitResponse, ULW_LOOP_OPERATIONS};
use ulw_loop_core::surface::UlwLoopToolkitSurface;

#[test] fn manifest_exposes_exact_operations() { let m=ulw_loop_manifest(); let names:Vec<_>=m.operations.iter().map(|o|o.name.as_str()).collect(); assert_eq!(names,ULW_LOOP_OPERATIONS); }
#[test] fn absent_session_identity_fails_closed() { let result=AgentToolkit::new(ToolkitContext { cwd:".".into(), session_id:"".into(), surface:UlwLoopToolkitSurface::LazyCodex },None); assert!(result.is_err()); if let Err(err)=result { assert_eq!(err.code,"ULW_LOOP_SESSION_ID_REQUIRED"); } }
#[test] fn checkpoint_template_uses_explicit_surface_roles() -> Result<(),Box<dyn std::error::Error>> { for surface in [UlwLoopToolkitSurface::OmoSenpi,UlwLoopToolkitSurface::LazyCodex] { let tmp=tempfile::tempdir()?; let t=AgentToolkit::new(ToolkitContext {cwd:tmp.path().to_string_lossy().into(),session_id:"template".into(),surface},None)?; assert!(matches!(t.create_goals(&CreateGoalsOptions {brief:"Template fixture".into(),goals:None,codex_goal_mode:None,force:None,validation_batches_json:None}),ToolkitResponse::Success{..})); let r=t.checkpoint(&ulw_loop_core::sdk::CheckpointArgs {print_template:Some(true),goal_id:None,status:None,evidence:None,codex_goal_json:None,quality_gate_json:None}); assert!(matches!(r,ToolkitResponse::Success{..})); } Ok(()) }
#[test] fn unknown_operation_is_rejected_at_dispatch_boundary() { let t=AgentToolkit::new(ToolkitContext {cwd:".".into(),session_id:"sdk-contract".into(),surface:UlwLoopToolkitSurface::LazyCodex},None).unwrap(); let r=t.dispatch(&serde_json::json!({"operation":"does-not-exist"})); match r { ToolkitResponse::Failure { error, .. } => assert_eq!(error.code,"ULW_LOOP_OPERATION_UNKNOWN"), _ => panic!("expected unknown-operation failure") } }
#[test] fn typed_help_envelope_is_success() { let t=AgentToolkit::new(ToolkitContext {cwd:".".into(),session_id:"sdk-contract".into(),surface:UlwLoopToolkitSurface::LazyCodex},None).unwrap(); assert!(matches!(t.help(),ToolkitResponse::Success{ok:true,..})); }
